  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Budgeting, Saving and Emergency Funds$j$, $j${"readings": [{"title": "Proverbs 21 (King James Version)", "url": "/portal/bible/Proverbs/21"}], "body": "A budget is a plan for your money. It lists your income and your expenses so that you decide where every dollar goes before you spend it. Fixed expenses, such as rent, stay the same each month. Variable expenses, such as food and gas, change. Discretionary spending covers wants. A simple starting guide is to give first, then plan about half of income for needs, about thirty percent for wants and about twenty percent for saving and debt payments. Adjust the percentages to your situation.\n\nTo build a budget, follow these steps: list your net income, list your fixed and variable expenses, set savings and giving goals, track your spending for a month, then compare plans to actual results and adjust. Apps and spreadsheets help, but the habit matters more than the tool. Pay yourself first by moving savings aside as soon as you are paid.\n\nSaving prepares you for the unexpected and for goals. An emergency fund is money set aside for surprises such as a car repair or a lost job. Many advisors suggest working toward three to six months of basic expenses, starting with a smaller goal such as one thousand dollars. Keep it in a safe, easy to reach account, such as an insured savings account. Short term goals, such as a phone or a trip, and long term goals, such as college or a home, each need their own plan.\n\nScripture praises planning. Proverbs 21:20 says, There is treasure to be desired and oil in the dwelling of the wise; but a foolish man spendeth it up. Proverbs 13:11 says, Wealth gotten by vanity shall be diminished: but he that gathereth by labour shall increase. Proverbs 6:6 says, Go to the ant, thou sluggard; consider her ways, and be wise.\n\nWorked example: a teen earns two hundred dollars a month, gives twenty, saves forty and spends the rest by plan. Common mistake: having no plan and wondering where the money went.\n\nYour task: (1) Define budget, fixed expense and variable expense. (2) List the steps to make a budget. (3) Create a sample monthly budget for a two hundred dollar income that includes giving and saving.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.FL", "script": "Welcome back. Listen, this unit is about the money in your own hands.\n\nA budget is a plan for your money. It lists income and expenses so you decide where every dollar goes before you spend it. Fixed expenses stay the same each month. Variable expenses change. A simple guide is to give first, then plan about half for needs, thirty percent for wants and twenty percent for saving and debt payments.\n\nNow watch this. To build a budget, list your net income, list your expenses, set savings and giving goals, track your spending for a month and adjust. Pay yourself first by moving savings aside when you are paid.\n\nAn emergency fund covers surprises like a car repair or a lost job. Start with a goal like one thousand dollars and work toward three to six months of basic expenses. Keep it in a safe, insured account.\n\nProverbs 21:20 says, There is treasure to be desired and oil in the dwelling of the wise; but a foolish man spendeth it up. Proverbs 13:11 says, he that gathereth by labour shall increase.\n\nYour task is to define budget terms, list the steps and make a sample budget. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Budgeting, Saving and Emergency Funds$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Banking, Credit, Debt and Credit Scores$j$, $j${"readings": [{"title": "Romans 13 (King James Version)", "url": "/portal/bible/Romans/13"}], "body": "Banks and credit unions offer checking accounts for daily spending and savings accounts that earn interest. Learn the fees, minimum balances and overdraft rules, and check that the institution is insured by the FDIC or, for credit unions, the NCUA. Debit cards take money directly from your account. Credit cards borrow money that you must repay.\n\nCredit means borrowing with a promise to repay, usually with interest. The annual percentage rate, or APR, is the yearly cost of borrowing. If you carry a balance on a credit card with a twenty percent APR, a thousand dollars of debt costs about two hundred dollars a year in interest, and paying only the minimum can keep you in debt for years. Pay the full statement balance each month and you avoid interest. In the United States, a person under twenty one must show income or have a cosigner to get a credit card. Loans such as car loans and student loans also carry interest and fees, so compare the total cost before borrowing.\n\nYour credit score, usually from 300 to 850, helps lenders decide whether to lend to you and at what rate. The main factors are payment history, the amount you owe compared with your limits, the length of your credit history, new credit applications, and the mix of credit types. Pay on time every time, keep balances low, and check your free credit reports at AnnualCreditReport.com.\n\nScripture warns about debt. Proverbs 22:7 says, The rich ruleth over the poor, and the borrower is servant to the lender. Romans 13:8 says, Owe no man any thing, but to love one another: for he that loveth another hath fulfilled the law. Debt is not always a sin, but it is a serious commitment, and Christians keep their word and repay what they borrow. Psalm 37:21 says, The wicked borroweth, and payeth not again.\n\nWorked example: you pay only the minimum on a card and the balance grows because interest is added. Common mistake: thinking that a credit limit is money you can afford to spend.\n\nYour task: (1) Define APR and credit score. (2) List three factors in a credit score. (3) Explain how to use a credit card without paying interest.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.FL", "script": "Welcome back. Listen, credit can be a tool or a trap, and you must know the difference.\n\nBanks and credit unions offer checking and savings accounts. Learn the fees and be sure the institution is insured. A debit card takes money from your account. A credit card borrows money you must repay.\n\nThe annual percentage rate, or APR, is the yearly cost of borrowing. At twenty percent, a thousand dollars of card debt costs about two hundred dollars a year in interest. Paying only the minimum keeps you in debt for years. Pay the full statement balance and you avoid interest.\n\nNow watch this. Your credit score runs from 300 to 850. The main factors are payment history, the amount you owe compared with your limits, the length of your history, new credit and your mix of credit. Pay on time and keep balances low.\n\nProverbs 22:7 says, the borrower is servant to the lender. Romans 13:8 says, Owe no man any thing, but to love one another. Psalm 37:21 says, The wicked borroweth, and payeth not again. Keep your word.\n\nYour task is to define APR and credit score, list three factors and explain how to avoid card interest. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Banking, Credit, Debt and Credit Scores$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Investing, Compound Interest and Risk$j$, $j${"readings": [{"title": "Ecclesiastes 11 (King James Version)", "url": "/portal/bible/Ecclesiastes/11"}], "body": "Saving keeps money safe. Investing puts money to work to grow over a long time, with the risk that the value can go down. Simple interest is paid only on the original amount. Compound interest is paid on the original amount plus the interest already earned, so growth speeds up over time. The earlier you start, the more time works for you.\n\nA quick way to estimate is the rule of 72. Divide 72 by the annual rate of return to find about how many years it takes money to double. At 8 percent, 72 divided by 8 is 9, so money roughly doubles in nine years. At 4 percent it takes about eighteen years. The same rule shows how fast debt can grow at a high interest rate.\n\nCommon investments include stocks, which are shares of ownership in a company, bonds, which are loans to governments or companies, and mutual funds and exchange traded funds, which hold many investments in one package. In general, higher possible returns come with higher risk. Diversification means spreading money across many investments so that one failure does not ruin you. Fees matter too, because they reduce returns every year. Retirement accounts such as a 401(k) at work or an IRA offer tax advantages, and if an employer offers a match, that is free money worth capturing.\n\nScripture supports diversifying and warns against get rich quick schemes. Ecclesiastes 11:2 says, Give a portion to seven, and also to eight; for thou knowest not what evil shall be upon the earth. Proverbs 28:20 says, A faithful man shall abound with blessings: but he that maketh haste to be rich shall not be innocent. Be wary of anyone who promises guaranteed high returns, because that is a classic sign of fraud.\n\nWorked example: one thousand dollars at 8 percent doubles to about two thousand in nine years and to about four thousand in eighteen years. Common mistake: waiting to start because the amount is small.\n\nYour task: (1) Explain compound interest. (2) Use the rule of 72 to estimate doubling time at 6 percent. (3) Explain diversification and name two warning signs of an investment scam.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.FL", "script": "Welcome back. Listen, saving protects your money, and investing helps it grow.\n\nCompound interest is interest on your original amount plus the interest you already earned. Growth speeds up over time, so start early. The rule of 72 estimates doubling time. Divide 72 by the annual return. At 8 percent, money doubles in about nine years.\n\nNow watch this. A stock is a share of ownership in a company. A bond is a loan to a government or company. A mutual fund or exchange traded fund holds many investments in one package. Higher possible returns come with higher risk. Diversification spreads your money so one failure does not ruin you. Watch the fees, and capture any employer match in a retirement plan.\n\nEcclesiastes 11:2 says, Give a portion to seven, and also to eight; for thou knowest not what evil shall be upon the earth. Proverbs 28:20 says, he that maketh haste to be rich shall not be innocent. Guaranteed high returns are a sign of fraud.\n\nYour task is to explain compound interest, use the rule of 72 at 6 percent and explain diversification and two scam warnings. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Investing, Compound Interest and Risk$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Taxes, Insurance, Fraud Protection and Giving$j$, $j${"readings": [{"title": "Malachi 3 (King James Version)", "url": "/portal/bible/Malachi/3"}], "body": "Most workers file a federal income tax return each year, usually by mid April, using information from forms such as the W2. You report income, claim deductions and credits you qualify for, and either pay more or receive a refund if too much was withheld. A refund is your own money returned, not a bonus. Keep records, file on time and be honest, because tax fraud is a crime.\n\nInsurance protects you from large losses by sharing risk among many people. You pay a premium, and if a covered loss happens the insurer pays, after you pay your deductible. Common types are health, auto, renters or homeowners, and life insurance. Florida requires drivers to carry certain minimum auto coverages, and renters insurance is inexpensive protection for belongings. Choose coverage you need, compare quotes and read what is excluded.\n\nFraud and identity theft are growing threats. Phishing uses fake emails, texts or calls that pretend to be a bank, a school or a government office to steal your information. Warning signs include pressure to act now, requests for gift cards, wire transfers or payment apps from strangers, and prizes you never entered to win. Protect yourself: never share your Social Security number, passwords or one time codes; use strong, different passwords and two step verification; check statements often; and freeze your credit if your information is stolen. Report scams to the Federal Trade Commission at ReportFraud.ftc.gov. Proverbs 14:15 teaches wisdom: The simple believeth every word: but the prudent man looketh well to his going.\n\nGod's people are also called to give. Malachi 3:10 says, Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it. 2 Corinthians 9:7 says, Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver. Giving is worship and trust, not a way to buy wealth. Generosity also includes helping the poor and supporting your church.\n\nWorked example: a teen gets a text saying a package needs a fee paid by gift card. This is a scam, so delete it and tell a trusted adult. Common mistake: acting quickly under pressure.\n\nYour task: (1) Define premium and deductible. (2) List four ways to protect yourself from fraud. (3) Write a personal giving plan that includes your church and a service project.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.FL", "script": "Welcome back. Listen, this lesson helps you keep what God has entrusted to you and use it well.\n\nMost workers file a federal tax return each year, usually by mid April. A refund is your own money returned, not a bonus. Keep records and be honest.\n\nInsurance shares risk. You pay a premium, and if a covered loss happens the insurer pays after you pay your deductible. Common types are health, auto, renters and life. Florida requires drivers to carry certain minimum auto coverages.\n\nNow watch this. Phishing uses fake emails, texts and calls to steal your information. Be alert to pressure to act now, requests for gift cards or payment apps, and prizes you never entered to win. Never share your Social Security number, passwords or codes. Use strong passwords and two step verification. Report scams to the Federal Trade Commission. Proverbs 14:15 says, the prudent man looketh well to his going.\n\nGod also calls us to give. Malachi 3:10 says, Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts. Second Corinthians 9:7 says, God loveth a cheerful giver. Giving is worship and trust, not a way to buy wealth.\n\nYour task is to define premium and deductible, list four fraud protections and write a giving plan. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Taxes, Insurance, Fraud Protection and Giving$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Financial Literacy$j$, $j${"prompt": "Write a report of at least 250 words on financial literacy. Use complete sentences and label each part. Proverbs 21:5 says, The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.\n\nPart 1: Create a sample monthly budget for a net income of one thousand dollars that includes giving, saving and both fixed and variable expenses, and explain your choices.\nPart 2: Explain an emergency fund and how you would build one.\nPart 3: Explain APR, credit scores and how to use credit wisely, with reference to Romans 13:8 or Proverbs 22:7.\nPart 4: Explain compound interest, the rule of 72, and diversification. Use the rule of 72 to estimate doubling time at 9 percent.\nPart 5: Explain insurance, two fraud protections and your personal plan for giving.", "rubric": "100 points. Part 1: 25 points. Part 2: 10 points. Part 3: 20 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Financial Literacy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Faithful Stewards$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes one money habit you want to build this year, (2) explains the first step you will take, (3) names one scam or money trap teens should avoid, and (4) connects your answer to Proverbs 21:20, Romans 13:8 or 2 Corinthians 9:7. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can saving and giving work together?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Faithful Stewards$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Budgeting, Saving and Emergency Funds$j$, $j${"questions": [{"q": "A budget is:", "options": ["A plan for your income and expenses", "A kind of loan", "A tax form", "A bank fee"]}, {"q": "An emergency fund is meant for:", "options": ["Unexpected costs", "Shopping sales", "Vacations only", "Gifts only"]}, {"q": "Paying yourself first means:", "options": ["Skipping bills", "Setting savings aside when you are paid", "Borrowing", "Spending first"]}, {"q": "Rent is usually a:", "options": ["Tax", "Fixed expense", "Gift", "Variable expense"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Budgeting, Saving and Emergency Funds$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,1,1}'::int[], array[$j$It tells your money where to go.$j$,$j$It prevents debt during surprises.$j$,$j$Saving is planned, not leftover.$j$,$j$It stays the same each month.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Budgeting, Saving and Emergency Funds$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Banking, Credit, Debt and Credit Scores$j$, $j${"questions": [{"q": "APR stands for:", "options": ["Annual profit report", "Average payment ratio", "Annual percentage rate", "Account payment record"]}, {"q": "The most important way to protect your credit score is:", "options": ["Paying on time", "Ignoring bills", "Maxing out cards", "Opening many cards"]}, {"q": "To avoid credit card interest you should:", "options": ["Pay the full statement balance each month", "Skip payments", "Pay only the minimum", "Use the limit fully"]}, {"q": "Romans 13:8 says:", "options": ["Trust riches", "Owe no man any thing", "Borrow freely", "Spend quickly"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Banking, Credit, Debt and Credit Scores$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,1}'::int[], array[$j$It is the yearly cost of borrowing.$j$,$j$Payment history carries the most weight.$j$,$j$No balance carried means no interest.$j$,$j$Debt is a serious commitment.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Banking, Credit, Debt and Credit Scores$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Investing, Compound Interest and Risk$j$, $j${"questions": [{"q": "Compound interest is paid on:", "options": ["Taxes", "Fees", "The original amount plus earned interest", "The original amount only"]}, {"q": "By the rule of 72, money at 8 percent doubles in about:", "options": ["9 years", "20 years", "72 years", "2 years"]}, {"q": "Diversification means:", "options": ["Borrowing to invest", "Putting everything in one stock", "Avoiding all risk", "Spreading money across many investments"]}, {"q": "A sign of an investment scam is:", "options": ["Slow growth", "Guaranteed high returns", "Public records", "Clear fees"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Investing, Compound Interest and Risk$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,1}'::int[], array[$j$Growth builds on growth.$j$,$j$72 divided by 8 is 9.$j$,$j$It reduces the harm of one failure.$j$,$j$No honest investment can guarantee high returns.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Investing, Compound Interest and Risk$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Taxes, Insurance, Fraud Protection and Giving$j$, $j${"questions": [{"q": "A premium is:", "options": ["The regular price you pay for insurance", "A loan", "A prize", "A tax refund"]}, {"q": "A deductible is:", "options": ["A bank fee", "A discount", "A tax form", "The amount you pay before insurance pays"]}, {"q": "A sign of a phishing scam is:", "options": ["A school notice", "Pressure to act now or pay with gift cards", "A bank letter you expected", "A clear statement"]}, {"q": "2 Corinthians 9:7 says God loveth:", "options": ["A proud lender", "A cheerful giver", "A hidden saver", "A quick spender"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Taxes, Insurance, Fraud Protection and Giving$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,1}'::int[], array[$j$Premiums buy protection.$j$,$j$It is your share of a covered loss.$j$,$j$Scammers use urgency.$j$,$j$Giving should come from the heart.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Taxes, Insurance, Fraud Protection and Giving$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Financial Literacy$j$, $j${"questions": [{"q": "A budget helps you decide:", "options": ["When to borrow", "Where every dollar goes before you spend it", "Which stocks will rise", "How to avoid all taxes"]}, {"q": "A three to six month emergency fund is meant to cover:", "options": ["Investments only", "Basic expenses", "Luxury items", "Entertainment"]}, {"q": "Credit scores usually range from:", "options": ["0 to 100", "300 to 850", "1 to 10", "500 to 5000"]}, {"q": "Paying only the minimum on a credit card balance usually:", "options": ["Saves money", "Raises your credit limit", "Keeps you in debt longer", "Eliminates interest"]}, {"q": "Using the rule of 72, money at 6 percent doubles in about:", "options": ["6 years", "72 years", "12 years", "2 years"]}, {"q": "Diversification reduces:", "options": ["Your income", "All taxes", "The harm if one investment fails", "Interest"]}, {"q": "Insurance works by:", "options": ["Guaranteeing profit", "Avoiding all loss", "Sharing risk among many people", "Replacing savings"]}, {"q": "Malachi 3:10 and 2 Corinthians 9:7 teach that giving is:", "options": ["A requirement of the tax code", "A tax", "An act of worship and trust", "A way to guarantee wealth"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Financial Literacy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,2,2,2,2,2}'::int[], array[$j$Planning prevents waste.$j$,$j$It protects against job loss or surprises.$j$,$j$Higher scores earn better rates.$j$,$j$Interest keeps growing.$j$,$j$72 divided by 6 is 12.$j$,$j$Do not put everything in one place.$j$,$j$Many pay premiums so a few can be covered.$j$,$j$Give with a cheerful heart.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Financial Literacy$j$ on conflict (item_id) do nothing;
